import {
  Building2,
  ClipboardList,
  FileText,
  Home,
  ShieldCheck,
  Users,
} from "lucide-react";

/**
 * Definición centralizada del menú. Cada nuevo módulo (de los 11 totales)
 * se agrega aquí como una entrada más, indicando con qué permiso(s) se
 * habilita (uno o varios códigos = OR).
 *
 * - `permissions: []` -> visible para cualquier usuario autenticado
 *   (ej. "Inicio").
 * - `enabled: false` -> se muestra como "Próximamente" (deshabilitado),
 *   útil mientras se van construyendo los módulos restantes.
 */
export const MENU_ITEMS = [
  {
    label: "Inicio",
    path: "/dashboard",
    icon: Home,
    permissions: [],
    enabled: true,
  },
  {
    label: "Empresas",
    path: "/dashboard/empresas",
    icon: Building2,
    permissions: ["companies.view"],
    enabled: false,
  },
  {
    label: "Gestión Documental",
    path: "/dashboard/documentos",
    icon: FileText,
    permissions: ["companies.view"],
    enabled: false,
  },
  {
    label: "Usuarios",
    path: "/dashboard/usuarios",
    icon: Users,
    permissions: ["users.view"],
    enabled: true,
  },
  {
    label: "Roles y Permisos",
    path: "/dashboard/roles",
    icon: ShieldCheck,
    permissions: ["roles.view", "roles.manage"],
    enabled: true,
  },
  {
    label: "Reportes",
    path: "/dashboard/reportes",
    icon: ClipboardList,
    permissions: ["companies.view"],
    enabled: false,
  },
];

/**
 * Filtra el menú según los permisos del usuario.
 * @param {(...codes: string[]) => boolean} hasPermission
 */
export const getMenuForUser = (hasPermission) =>
  MENU_ITEMS.filter(
    (item) => item.permissions.length === 0 || hasPermission(...item.permissions)
  );
